<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Super Admin','College Admin','Principal','HOD');check_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){try{$id=(int)$_POST['id'];$status=trim($_POST['status']);$remarks=trim($_POST['remarks']);db()->beginTransaction();db()->prepare('UPDATE applications SET status=?,current_stage=?,updated_at=NOW() WHERE id=?')->execute([$status,$status,$id]);db()->prepare('INSERT INTO application_history(application_id,status,stage,remarks,changed_by) VALUES(?,?,?,?,?)')->execute([$id,$status,$status,$remarks,actor_id()]);db()->commit();AuditService::log('APPROVAL','applications',$id,'Application '.$status);$_SESSION['flash']=['success','Application updated'];}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$_SESSION['flash']=['danger',$e->getMessage()];}redirect('approvals.php');}$rows=db()->query('SELECT * FROM applications ORDER BY id DESC LIMIT 100')->fetchAll();page_top('Approval Workflow Center');flash();?><div class="card p-3 table-responsive"><table class="table"><tr><th>ID</th><th>Type</th><th>Title</th><th>Status</th><th>Stage</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['id'])?></td><td><?=e($r['application_type'])?></td><td><?=e($r['title'])?></td><td><?=e($r['status'])?></td><td><?=e($r['current_stage'])?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($r['id'])?>"><select name="status" class="form-select form-select-sm"><option>Under Verification</option><option>Correction Required</option><option>Approved</option><option>Rejected</option><option>Admitted</option></select><input name="remarks" class="form-control form-control-sm" placeholder="Remarks"><button class="btn btn-sm btn-primary">Apply</button></form></td></tr><?php endforeach;?></table></div><?php page_bottom(); ?>